CASES=[
{'n':'ע״א 2965/08 סגנון שרותי תקשוב בע״מ נ׳ פקיד שומה פתח-תקווה','tag':'תכנון חיובי מול שלילי','story':'החברה רכשה מניות של חברות שהודיעו על חלוקת דיבידנד, קיבלה את הדיבידנד בפטור ממס, ומכרה את המניות בהפסד. את ההפסד ביקשה לקזז ("כיבוס דיבידנד").','hold':'בית המשפט העליון (21.6.2011) קבע שהעסקאות מלאכותיות. הוא הבחין בין <b>תכנון מס חיובי</b>, שמנצל הטבה שהמחוקק התכוון להעניק ולכן לגיטימי, לבין <b>תכנון מס שלילי</b>, שמנצל פרצה בניגוד לתכלית החוק ונבחן לפי ס׳ 86. נקבע גם מעבר ממבחן "בלעדיות המטרה הפיסקלית" למבחן <b>יסודיות הטעם המסחרי</b>: הטעם המסחרי צריך להיות כזה שבלעדיו העסקה לא הייתה מתבצעת. בקשה לדיון נוסף נדחתה.'},
{'n':'ע״א 550/22 עמרם נ׳ פקיד שומה ירושלים 3','tag':'סיווג שונה וסיווג מחדש','story':'בעל מניות מכר לחברה שבשליטתו את זכויותיו בסימן מסחרי תמורת כ-8.4 מיליון אירו, ודיווח על כך כרווח הון פטור. פקיד השומה קבע שהעסקה מלאכותית וסיווג את הכספים שנמשכו מהחברה כהכנסת עבודה, ולחלופין כדיבידנד.','hold':'בעליון (29.8.2023) ויתר המערער, בהמלצת בית המשפט, על הטענה שהעסקה אינה מלאכותית. בית המשפט הבחין בין <b>סיווג מחדש</b> (התעלמות מהעסקה מכוח ס׳ 86) לבין <b>סיווג שונה</b> (קבלת העובדות והארתן באור אחר). הוא קבע שהמשיכות ימוסו <b>כדיבידנד</b> לפי ס׳ 2(4), בהשראת ההסדר שבס׳ 3(ט1), ולא כהכנסת עבודה. קנס הגירעון אושר.'},
{'n':'ע״א 10666/03 שטרית נ׳ פקיד שומה תל אביב 4','tag':'פירוק והקמה מחדש','story':'אדריכל שבחברתו נצברו רווחים הקים חברה חדשה זהה (אותם עובדים, משרדים, תקנון ופעילות) ופירק את הישנה. כך ביקש ליהנות משיעור מס מופחת על רווחים ראויים לחלוקה ומפטור על פיצויים.','hold':'בית המשפט העליון קבע שלפירוק לא היה טעם מסחרי מלבד חיסכון במס, ולכן העסקה <b>מלאכותית</b>. נדחתה הטענה שכל ניצול של הטבת מס לגיטימי מעצם הגדרתו, משום שזו הייתה מרוקנת את ס׳ 86 מתוכן. עם זאת הודגש שלא כל פירוק שמנצל הטבה פסול. ההכרעה תלויה בנסיבות, ובמיוחד בקיומה של "חברת המשך" זהה.'},
{'n':'ע״א 4374/05 ראובני נ׳ פקיד שומה תל אביב 4','tag':'מוניטין דרך חברה','story':'סוכן ביטוח עצמאי העביר את עסקו לחברת אחזקות, ובהמשך נכנס צד שלישי לשותפות בחברה חדשה. המבנה נועד ליהנות משיעור מס נמוך במכירת מוניטין במקום החיוב שהיה חל במכירה ישירה.','hold':'בית המשפט העליון (19.9.2007) קבע שהעסקה מלאכותית ואישר את סיווגה לפי מהותה. הטענה שהשותף רצה חברה "נקייה" נדחתה, כי לא הוכחה בראיות והשותף לא העיד. הלקח: בחירה במבנה הזול לגיטימית רק אם הטעם העסקי הנטען אמיתי ומוכח.'}
]
QS=[
{'q':'מהו ההבדל המרכזי בין הימנעות ממס בלתי נאותה לבין העלמת מס?','o':['בהימנעות העובדות אמיתיות ומדווחות, ובהעלמה יש הסתרה או מצג כוזב בכוונה להתחמק ממס','הימנעות היא תמיד מותרת, והעלמה מותרת רק בסכומים קטנים','הימנעות נוגעת למס הכנסה בלבד, והעלמה נוגעת למע״מ בלבד','אין הבדל, ושני המונחים מתארים עבירה לפי ס׳ 220'],'c':0,'why':['נכון. הימנעות בלתי נאותה היא שימוש בפעולות אמיתיות בניגוד לתכלית החוק, והתגובה לה אזרחית (ס׳ 86). העלמה כרוכה בהסתרה או במרמה בכוונה להתחמק ממס, והיא עבירה לפי ס׳ 220.','הימנעות בלתי נאותה אינה "מותרת" במובן שהרשות חייבת לכבד אותה: פקיד השומה רשאי להתעלם ממנה. ואין לעבירת ההעלמה פטור לסכומים קטנים.','שתי התופעות קיימות בכל מסי ישראל, ובחוקי המס השונים יש הוראות מקבילות. החלוקה בין סוגי המס אינה ההבחנה.','יש הבדל מהותי. ס׳ 220 דורש כוונה להתחמק ממס ומעשה כמו השמטה, אמרה כוזבת או מרמה, וזה לא קיים בתכנון שקוף.']},
{'q':'לפי פסק דין סגנון, מהו "תכנון מס חיובי"?','o':['כל תכנון שהצליח להפחית את המס','תכנון שבו הנישום שילם יותר מס מהנדרש','תכנון שמנצל הטבה שהמחוקק יצר במכוון כדי לעודד התנהגות מסוימת','תכנון שאושר בדיעבד בפסק דין'],'c':2,'why':['הצלחה בהפחתת מס אינה הקריטריון. גם תכנון שלילי מפחית מס, וזה בדיוק מה שמעורר את הבעיה.','זה אינו תכנון כלל, וממילא אין בו שאלה של לגיטימיות.','נכון. תכנון חיובי נשען על מדיניות מכוונת ומוצהרת של המחוקק, ולכן הוא לגיטימי גם אם המניע היחיד הוא מס.','הסיווג נעשה לפי תכלית החוק ולא לפי תוצאת התדיינות. תכנון יכול להיות חיובי בלי שהגיע לבית משפט.']},
{'q':'מה השתנה במבחן הטעם המסחרי בעקבות פסק דין סגנון?','o':['המבחן בוטל, ובמקומו נקבע שכל תכנון שלילי הוא מלאכותי','די בטעם מסחרי כלשהו, גם שולי, כדי להכשיר את העסקה','הטעם המסחרי נבחן רק אם הנישום ביקש החלטת מיסוי','נדרש טעם מסחרי יסודי, כזה שבלעדיו הנישום לא היה מבצע את העסקה'],'c':3,'why':['המבחן לא בוטל. סגנון גם קבע שתכנון שלילי אינו מלאכותי אוטומטית, אלא נבחן לפי ס׳ 86.','זו הגישה הקודמת ("בלעדיות המטרה הפיסקלית") שסגנון זנח. כיום טעם שולי אינו מספיק.','אין קשר בין מבחן הטעם המסחרי לבין הגשת בקשה להחלטת מיסוי. המבחן חל בכל בחינה של ס׳ 86.','נכון. סגנון עבר למבחן "יסודיות הטעם המסחרי". רק טעם עסקי שבלעדיו העסקה לא הייתה נעשית מכשיר תכנון שלילי.']},
{'q':'איזה מבחן הוצע בפסק דין גוטשל לזיהוי תכנון מס שלילי?','o':['האם המחוקק, אילו צפה את התכנון, היה משנה את החוק כדי למנוע אותו','האם יועץ המס קיבל שכר טרחה מותנה','האם החיסכון במס עלה על מיליון ש״ח','האם העסקה נעשתה בין קרובים'],'c':0,'why':['נכון. זהו מבחן "המחוקק ההיפותטי". תשובה חיובית מצביעה על ניצול פרצה בניגוד לתכלית, כלומר על תכנון שלילי.','שכר טרחה מותנה רלוונטי לחובת הדיווח על חוות דעת לפי ס׳ 131ד, ולא לסיווג התכנון.','גובה החיסכון אינו מבחן הלגיטימיות. ספי סכום מופיעים בהוראות הדיווח, לא במבחן התכנון.','עסקה בין קרובים עשויה לעורר חשד, אבל זו אינה ההגדרה של תכנון שלילי.']},
{'q':'יחיד בחר לפתוח עסק באמצעות חברה ולא כעוסק מורשה, כדי ליהנות ממס חברות ולדחות את מס הדיבידנד. לחברה פעילות עסקית אמיתית ולקוחות רבים. כיצד יסווג התכנון?','o':['תכנון שלילי, ולכן העסקה מלאכותית','העלמת מס, משום שמטרתו לשלם פחות','תכנון ניטרלי ולגיטימי: בחירה בין חלופות שהמחוקק השאיר פתוחות','עסקה בדויה, משום שהחברה היא רק כסות'],'c':2,'why':['המחוקק עצמו יצר את המודל הדו-שלבי ומאפשר לבחור בין יחיד לחברה. כשיש פעילות אמיתית, אין כאן ניצול פרצה.','העלמה דורשת הסתרה או מרמה. כאן הכול מדווח ואמיתי.','נכון. זו הדוגמה הקלאסית לתכנון ניטרלי. הדבר שונה כשמדובר ב"חברת ארנק" של שכיר, שאותה חוסם ס׳ 62א.','עסקה בדויה היא עסקה שלא התקיימה באמת. החברה פועלת בפועל, ולכן היא אינה בדויה.']},
{'q':'מנהל בכיר בחברה ציבורית התפטר ונחתם הסכם לפיו חברה בבעלותו המלאה תספק "שירותי ניהול" לאותה חברה ציבורית. המנהל ממשיך לכהן כנושא משרה. איזו הוראה רלוונטית במיוחד?','o':['ס׳ 94ג לפקודה','ס׳ 62א לפקודה, המייחס את ההכנסה ליחיד כהכנסה מיגיעה אישית','ס׳ 100א לפקודה','ס׳ 158ג לפקודה'],'c':1,'why':['ס׳ 94ג עוסק בהפחתת הפסד הון בגובה דיבידנד שהתקבל ("כיבוס דיבידנד"), ולא בהכנסה משירותים.','נכון. ס׳ 62א חל כשהכנסת חברת המעטים נובעת מפעילות בעל השליטה כנושא משרה או כנותן שירותי ניהול בחבר בני אדם אחר. ההכנסה תיוחס לו כהכנסה מיגיעה אישית, בכפוף לחריגים שבסעיף.','ס׳ 100א עוסק במס יציאה לתושב שחדל להיות תושב ישראל.','ס׳ 158ג עוסק בסמכות ליתן החלטות מיסוי, ולא במיסוי הכנסה משירותים.']},
{'q':'בעלת מניות מהותי משכה מהחברה הלוואה גבוהה ולא החזירה אותה לאורך זמן. איזו הוראה ספציפית עשויה לחול?','o':['ס׳ 3(ט1) לפקודה, הרואה במשיכה הכנסה בתנאים שבסעיף','ס׳ 131ה לפקודה','ס׳ 125ג לפקודה','ס׳ 97(ב2) לפקודה'],'c':0,'why':['נכון. ס׳ 3(ט1) חוסם משיכת כספים מחברה בידי בעל מניות מהותי בלי מס. אם המשיכה לא הוחזרה עד מועד החיוב, היא נחשבת הכנסה לפי מנגנון הסעיף.','ס׳ 131ה עוסק בחובת דיווח על עמדה המנוגדת לעמדה מפורסמת של רשות המסים, ולא במשיכות.','ס׳ 125ג קובע את שיעורי המס על ריבית. הוא אינו הופך משיכה להכנסה.','ס׳ 97(ב2) פוטר תושב חוץ מרווח הון על ניירות ערך הנסחרים בבורסה בישראל. אין לו קשר למשיכות.']},
{'q':'מהו "תכנון מדף" לעניין ס׳ 131ד?','o':['תכנון שנעשה על ידי חברה ציבורית בלבד','כל חוות דעת שניתנה על ידי עורך דין','חוות דעת בעלת תוכן אחיד שניתנה לשלושה לפחות בתוך שנתיים ואינה תלויה בעיקרה בנסיבות המקבל, או חוות דעת שהוצעה ביוזמת נותנה תוך חיוב בסודיות','תכנון שאושר בהחלטת מיסוי ופורסם באתר רשות המסים'],'c':2,'why':['ההגדרה אינה תלויה בסוג המקבל. היא עוסקת בטיב חוות הדעת.','לא כל חוות דעת חייבת בדיווח. נדרש שכר טרחה מותנה או תכנון מדף.','נכון. אלה שתי החלופות שבהגדרת "תכנון מדף" בס׳ 131ד(א): תוכן אחיד שהופץ לשלושה לפחות, או הצעה ביוזמת היועץ בצירוף חובת סודיות.','החלטת מיסוי שפורסמה אינה "תכנון מדף". אדרבה, החלטה כזו מעניקה ודאות ולא מטילה חובת דיווח בגינה.']},
{'q':'חברה גדולה נקטה בדוח עמדה המנוגדת לעמדה שפרסמה רשות המסים, ויתרון המס ממנה הוא 6 מיליון ש״ח בשנה. החברה לא סימנה זאת בטופס. מה הדין?','o':['אין חובה לדווח, כי מותר לחלוק על רשות המסים','החברה תיחשב כמי שלא הגישה דוח, ותיתכן חשיפה לקנס גירעון מוגבר','העמדה בטלה מאליה, והחברה תורשע בעבירה לפי ס׳ 220','חובת הדיווח חלה רק אם החברה קיבלה חוות דעת בכתב'],'c':1,'why':['מותר לחלוק על הרשות, אבל אם התקיימו התנאים חייבים לסמן זאת בדוח. החופש לחלוק אינו פוטר מגילוי.','נכון. זו "עמדה חייבת בדיווח" לפי ס׳ 131ה, כי היתרון עולה על 5 מיליון ש״ח בשנה (בכפוף לסף ההכנסה של הנישום). מי שלא דיווח נחשב כמי שלא הגיש דוח (ס׳ 131ה(ה)), ובתנאי ס׳ 191(ג1) ייתכן קנס של 30%.','אי-דיווח אינו הופך עמדה משפטית לבטלה ואינו עבירת העלמה כשלעצמו. התוצאות קבועות בס׳ 131ה ובס׳ 191.','החובה לפי ס׳ 131ה עצמאית ואינה תלויה בקבלת חוות דעת. חוות דעת היא מסלול דיווח נפרד (ס׳ 131ד).']},
{'q':'מתכנן מבקש החלטת מיסוי לגבי עסקה במקרקעין החייבת במס שבח. מתי עליו להגיש את הבקשה?','o':['בכל עת עד תום התיישנות השומה','רק לאחר קבלת שומת מס שבח','עד המועד להגשת הדוח השנתי למס הכנסה','לפני מועד ביצוע הפעולה נושא הבקשה'],'c':3,'why':['אין בפקודה מסלול כזה. בקשה להחלטת מיסוי כפופה למועדים שבס׳ 158ד.','החלטת מיסוי נועדה לתת ודאות מראש. אחרי שומה המסלול הוא השגה או ערר.','זה המועד הכללי במס הכנסה. במיסוי מקרקעין ובמע״מ הכלל שונה.','נכון. לפי ס׳ 158ד(ב), בקשה בעניין מס לפי חוק מיסוי מקרקעין או חוק מע״מ תוגש לפני ביצוע הפעולה.']},
{'q':'נישום קיבל החלטת מיסוי בהסכם, ולאחר מכן הוא סבור שתנאיה מכבידים מדי. האם יוכל לערער עליה?','o':['כן, לבית המשפט המחוזי בתוך 30 יום','לא. על החלטת מיסוי בהסכם אין ערעור','כן, אבל רק לבית המשפט העליון','כן, כחלק מערעור על השומה בכל מקרה'],'c':1,'why':['אין זכות ערעור עצמאית על החלטת מיסוי בהסכם.','נכון. ס׳ 158ג(ה) קובע שעל החלטת מיסוי בהסכם לא יהיה ערעור. ההסכמה היא שמצדיקה את חסימת הערעור.','גם לבית המשפט העליון אין מסלול ערעור ישיר על החלטה כזו.','זה המסלול רק להחלטת מיסוי <i>שלא</i> בהסכם, שעליה ניתן לערער כחלק מערר או ערעור על השומה.']},
{'q':'במסגרת "סיווג שונה" כפי שתואר בפרשת עמרם, מה עושה פקיד השומה?','o':['מקבל את העובדות כפי שהוצגו, אך נותן להן משמעות משפטית-כלכלית אחרת','מתעלם מהעסקה ובונה במקומה עסקה חלופית','מגיש כתב אישום בגין העלמת מס','מבטל החלטת מיסוי שניתנה לנישום'],'c':0,'why':['נכון. בסיווג שונה העובדות אינן במחלוקת. המחלוקת היא על האופן שבו יש לסווג אותן משפטית.','זה "סיווג מחדש", שנשען על ס׳ 86 ודורש לעמוד בתנאיו.','סיווג הוא כלי אזרחי של שומה. כתב אישום שייך למישור הפלילי, ולא לכך נועד הסיווג.','ביטול החלטת מיסוי אינו ענייננו. סיווג שונה עוסק בהבנת עסקה שבוצעה.']},
{'q':'מה קבע בית המשפט העליון בפרשת עמרם לגבי הכספים שמשך בעל המניות מהחברה?','o':['שהם רווח הון פטור, משום שמקורם במכירת סימן מסחרי','שהם הכנסת עבודה לפי ס׳ 2(2), משום שהיה מנכ״ל','שהם דיבידנד לפי ס׳ 2(4), בהשראת ההסדר שבס׳ 3(ט1)','שהם הכנסה פטורה, כי לא נגבתה עליהם ריבית'],'c':2,'why':['טענת הפטור נפלה כשהמערער ויתר בעליון על הטענה שהעסקה אינה מלאכותית.','זו הייתה עמדת פקיד השומה, ובית המשפט דחה אותה. חזקת הכנסת העבודה מעניין ברנע הוגבלה לתשלומים שניתנו בשל יחסי עבודה.','נכון. בית המשפט סיווג את המשיכות כדיבידנד. הוא הסתמך על ס׳ 3(ט1), שאמנם לא חל בשנות המס הנדונות אך משקף את דעת המחוקק.','אין פטור כזה. העדר ריבית אינו הופך משיכה להכנסה פטורה.']},
{'q':'בפרשת שטרית נטען שכל ניצול של הטבת מס הקבועה בחוק הוא לגיטימי מעצם הגדרתו. מה השיב בית המשפט העליון?','o':['קיבל את הטענה, והורה לבטל את השומה','קבע שהטענה נכונה רק לגבי חברות ציבוריות','קבע שהטענה רלוונטית רק בהליך פלילי','דחה את הטענה, משום שקבלתה הייתה מרוקנת את ס׳ 86 מתוכן'],'c':3,'why':['הערעור נדחה והעסקה נקבעה כמלאכותית.','אין בפסק הדין הבחנה כזו בין סוגי חברות.','הדיון היה אזרחי, במסגרת ערעור מס. השאלה הייתה אם ס׳ 86 חל.','נכון. בית המשפט קבע שאם כל ניצול של הטבה היה לגיטימי, הסמכות להתעלם מעסקה מלאכותית לא הייתה שווה דבר. עם זאת הוא הדגיש שלא כל פירוק שמנצל הטבה פסול.']},
{'q':'בשני תיקים דומים של פירוק חברה והקמת חברה חדשה, באחד (זלינגר) זכה הנישום ובשני (ראובני) הפסיד. מה היה ההבדל המכריע לפי ניתוח הפסיקה?','o':['בתיק שבו זכה הנישום הוכח בעדות צד שלישי טעם עסקי לא-מיסויי אמיתי','בתיק שבו זכה הנישום שיעור המס היה גבוה יותר','בתיק שבו הפסיד הנישום לא הוגש דוח שנתי','בתיק שבו זכה הנישום ניתנה החלטת מיסוי מוקדמת'],'c':0,'why':['נכון. האחיינית שהצטרפה העידה שהקמת חברה חדשה הייתה תנאי שלה. בראובני הטענה העסקית לא הוכחה והשותף לא העיד. ההבדל היה ראייתי.','שיעור המס לא היה ההבדל. בשני המקרים נבחר מבנה שהפחית מס.','אין ממצא כזה. המחלוקת הייתה על מלאכותיות ולא על אי-הגשת דוח.','לא נטען שניתנה החלטת מיסוי, וזה לא היה הבסיס להכרעה.']},
{'q':'כיצד ניתן לתאר את גישת המשפט הישראלי לחופש תכנון המס, כפי שבאה לידי ביטוי בפרשת חזון?','o':['תכנון מס אסור, אלא אם קיבל אישור מראש','עצם הבחירה במבנה משפטי דל מסים אינה הופכת אותו למלאכותי או בדוי, ומותר לנצל הוראות פטור או הקלה','כל מבנה שמפחית מס נחשב בדוי עד שיוכח אחרת','חופש התכנון קיים רק במיסוי מקרקעין'],'c':1,'why':['אין חובה לקבל אישור מראש. החלטת מיסוי היא כלי רשות לוודאות, לא תנאי לחוקיות.','נכון. כך נקבע מפי הנשיא שמגר. נקודת המוצא היא חופש התכנון, ובכפוף לכלים האנטי-תכנוניים.','אין חזקה כזו. להפך, מבנה דל מס אינו חשוד מעצם היותו כזה.','העיקרון כללי וחל בכל דיני המס.']},
{'q':'חברה קנתה מניה זמן קצר לפני חלוקת דיבידנד, קיבלה דיבידנד בין-חברתי פטור, ומכרה את המניה בהפסד כעבור כמה חודשים. מה הדין לפי הוראה ספציפית בפקודה?','o':['ההפסד מותר במלואו, משום שהדיבידנד פטור','הדיבידנד ימוסה ב-30% בידי החברה','החברה חייבת בדיווח לפי ס׳ 131ה בלבד','הפסד ההון יופחת בסכום הדיבידנד שהתקבל ב-24 החודשים שקדמו למכירה, אך לא יותר מסכום ההפסד'],'c':3,'why':['זה בדיוק התכנון שהמחוקק חסם. הפטור על הדיבידנד אינו מכשיר את ההפסד.','דיבידנד בין-חברתי ממקור ישראלי אינו נכלל בהכנסה החייבת של החברה (ס׳ 126(ב)). הפתרון אינו מיסוי הדיבידנד אלא הקטנת ההפסד.','ס׳ 131ה עוסק בעמדות המנוגדות לעמדות מפורסמות. ההסדר הספציפי כאן מהותי ולא רק דיווחי.','נכון. זהו ס׳ 94ג ("הפחתת הדיבידנד"), שנחקק בעקבות תופעת כיבוס הדיבידנד שנדונה בסגנון. הוא אינו חל על דיבידנד שעליו שולם מס בשיעור של 15% או יותר.']},
{'q':'רופא העביר דירה מניבה במתנה לבנו הקטין ורשם אותה על שמו, אך דמי השכירות ממשיכים להיכנס לחשבונו של הרופא ומשמשים אותו. מה הסיכון העיקרי?','o':['ההעברה תיחשב העלמת מס פלילית בכל מקרה','אין סיכון: מתנה לקרוב תמיד מכירה בילד כבעל ההכנסה','פקיד השומה עשוי לטעון שזו "הסבה שאינה מופעלת למעשה" לפי ס׳ 86, ולייחס את ההכנסה לאב','הדירה תחויב במס יציאה לפי ס׳ 100א'],'c':2,'why':['כשהעובדות דווחו בגלוי, השאלה היא אזרחית. העלמה דורשת הסתרה או מרמה.','לא תמיד. בפרשת גריל זכה ההורה כי הוכיח שהילדים הם בעלי ההכנסה. אבל כשההנאה בפועל נשארת אצל המעביר, ההכרה בהסבה בספק.','נכון. ס׳ 86 מתיר להתעלם מ"הסבה ... אינה מופעלת למעשה". אם הבן אינו נהנה בפועל מההכנסה, ההכנסה עשויה להיות מיוחסת לאב.','ס׳ 100א חל על מי שחדל להיות תושב ישראל, ואין לו קשר להעברה בתוך המשפחה.']},
{'q':'לפי ס׳ 191(ג1), באיזה מהמצבים הבאים רשאי פקיד השומה להטיל קנס גירעון של 30% (בהתקיים ספי הגירעון)?','o':['כשהנישום הגיש את הדוח באיחור של חודש','כשהגירעון נובע מתכנון שנקבע בשומה סופית כעסקה מלאכותית שהנישום לא דיווח עליה','כשהנישום ביקש החלטת מיסוי ונדחה','כשהנישום ערער על השומה והפסיד'],'c':1,'why':['איחור בהגשה מטופל בקנס על אי-הגשת דוח (ס׳ 188), ולא בקנס גירעון של 30%.','נכון. ס׳ 191(ג1)(3) מונה תכנון שנקבע בשומה סופית כעסקה מלאכותית ולא דווח, או עסקה בדויה. נדרש גם גירעון של יותר מ-500 אלף ש״ח לשנה שעולה על 50% מהמס.','דחיית בקשה להחלטת מיסוי אינה עילה לקנס. הקנס חל כשפועלים בניגוד להחלטה מפורשת שניתנה ולא מדווחים על כך.','הפסד בערעור כשלעצמו אינו עילה לקנס המוגבר. נדרשת אחת העילות המנויות.']},
{'q':'מה קובעת הרישה של ס׳ 131ה(א)(1) כתנאי ראשון להגדרת "עמדה חייבת בדיווח"?','o':['שהעמדה הובאה בחוות דעת של רואה חשבון','שהעמדה נוגעת לעסקה עם תושב חוץ','שהעמדה אושרה על ידי פקיד השומה','שהעמדה עומדת בניגוד לעמדה שפרסמה רשות המסים עד תום שנת המס שלגביה מוגש הדוח'],'c':3,'why':['קבלת חוות דעת היא מסלול דיווח נפרד (ס׳ 131ד). היא אינה תנאי של ס׳ 131ה.','אין בהגדרה דרישה לרכיב בין-לאומי.','עמדה שאושרה אינה עמדה "מנוגדת", ואין דרישה כזו בהגדרה.','נכון. זה התנאי הראשון. התנאי השני הוא שיתרון המס עולה על 5 מיליון ש״ח בשנה או על 10 מיליון ש״ח במהלך עד ארבע שנות מס.']}
]
